[{"order":1,"type":"heading","text":"Modular Routing with express.Router in Express.js"},{"order":2,"type":"paragraph","text":"As Express applications grow, keeping all your route definitions in a single app.js or server.js file becomes unmaintainable. The express.Router class allows you to create modular, mountable route handlers. A Router instance is a complete middleware and routing system; for this reason, it is often referred to as a "mini-app"."},{"order":3,"type":"subheading","text":"Prerequisites and Project Setup"},{"order":4,"type":"paragraph","text":"Before we begin, ensure you have Node.js installed. Create a new directory for your project, initialize it, and install Express."},{"order":5,"type":"code","text":"mkdir express-modular-routing
cd express-modular-routing
npm init -y
npm install express"},{"order":6,"type":"subheading","text":"Creating a Router Module"},{"order":7,"type":"paragraph","text":"Let us create a dedicated routes folder and a specific file for handling user-related routes, named userRoutes.js."},{"order":8,"type":"code","text":"const express = require('express');
const router = express.Router();

// Middleware specific to this router
router.use((req, res, next) => {
    console.log('Time: ', Date.now());
    next();
});

// Define the home page route
router.get('/', (req, res) => {
    res.send('User home page');
});

// Define the about route
router.get('/profile', (req, res) => {
    res.send('User profile page');
});

module.exports = router;"},{"order":9,"type":"subheading","text":"Creating Another Router Module"},{"order":10,"type":"paragraph","text":"Similarly, create an itemRoutes.js file to handle product or item endpoints."},{"order":11,"type":"code","text":"const express = require('express');
const router = express.Router();

router.get('/', (req, res) => {
    res.send('Items list');
});

router.get('/:id', (req, res) => {
    res.send('Item ID: ' + req.params.id);
});

module.exports = router;"},{"order":12,"type":"subheading","text":"Mounting the Routers in the Main Application"},{"order":13,"type":"paragraph","text":"Now, create your main application entry point, app.js. Use the app.use() method to mount the routers on specific paths."},{"order":14,"type":"code","text":"const express = require('express');
const app = express();
const PORT = 3000;

const userRoutes = require('./routes/userRoutes');
const itemRoutes = require('./routes/itemRoutes');

// Mount the routers
app.use('/users', userRoutes);
app.use('/items', itemRoutes);

app.get('/', (req, res) => {
    res.send('Main Application Root');
});

app.listen(PORT, () => {
    console.log('Server is running on port ' + PORT);
});"},{"order":15,"type":"subheading","text":"Benefits of Modular Routing"},{"order":16,"type":"bullet_point","text":"Separation of Concerns: Each resource (users, items, orders) has its own dedicated file."},{"order":17,"type":"bullet_point","text":"Maintainability: Codebases are easier to scale, debug, and navigate."},{"order":18,"type":"bullet_point","text":"Router-level Middleware: You can apply middleware exclusively to a specific group of routes without affecting the entire application."}]
